    private String appendMissing(String s, int a) {
        boolean[] used = new boolean[26];
        int start = Math.max(0, s.length() - a);
        for (int i = s.length() - 1; i >= start; i--)
            used[s.charAt(i) - 'a'] = true;

        StringBuilder sb = new StringBuilder(s);
        int need = a;
        for (int i = 0; i < 26 && need > 0; i++) {
            if (used[i])
