            sb.append((char) ('a' + i));
            need--;
        }
        return sb.toString();
    }

    private String appendLast(String s, int b) {
        char ch = s.charAt(s.length() - 1);
        StringBuilder sb = new StringBuilder(s);
        for (int i = 0; i < b; i++)
            sb.append(ch);
        return sb.toString();
